import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { request, signIn } from './lib/local-commerce.mjs';

// Retire only the exact synthetic signature generated by UI/scripts/smoke-commerce.mjs.
// No original mapped product, inventory, price, order or database row is deleted.
const owner = JSON.parse(readFileSync(join(process.env.APPDATA, 'Microsoft/UserSecrets/SRECommerce-LegacyDemo-Development/secrets.json'), 'utf8'));
const mapping = JSON.parse(readFileSync('artifacts/legacy-demo-catalog-mapping.json', 'utf8'));
if (mapping.tenantId !== owner.TenantId || Object.keys(mapping.products).length !== 1000) throw new Error('OriginalMappingMismatch');
const original = new Set(Object.values(mapping.products));
const token = await signIn('http://localhost:5181', owner.OwnerEmail, owner.OwnerPassword, owner.TenantId);
const path = '/api/v1/tenants/' + owner.TenantId + '/catalog';
const result = await (await request('http://localhost:5185', path + '/products?pageSize=100&search=000%20Browser%20smoke', { token })).json();
if (result.total > 20) throw new Error('SyntheticReviewLimitExceeded');
function owned(product) {
  const marker = /^000 Browser smoke ([a-f0-9]{10})$/.exec(product.name);
  return marker && !original.has(product.id) && product.slug === 'browser-smoke-' + marker[1] && product.variants.length === 1 && product.variants[0].sku === 'UI-' + marker[1].toUpperCase();
}
const candidates = result.items.filter(product => product.status !== 2 && owned(product));
if (candidates.length !== result.items.filter(product => product.status !== 2).length) throw new Error('UnexpectedProductPreserved');
const archived = [];
if (process.argv.includes('--apply')) for (const product of candidates) {
  const fresh = await (await request('http://localhost:5185', path + '/products/' + product.id, { token })).json();
  if (!owned(fresh)) throw new Error('ProductIdentityChanged');
  await request('http://localhost:5185', path + '/products/' + product.id + '/archive', { token, method: 'POST', body: { version: fresh.version }, status: 204 }); archived.push({ id: product.id, slug: product.slug });
}
const report = { sampledAt: new Date().toISOString(), applied: process.argv.includes('--apply'), matched: candidates.map(p => ({ id: p.id, slug: p.slug })), archived, originalsProtected: original.size, deletedRows: 0 };
mkdirSync('artifacts/review-website', { recursive: true }); writeFileSync('artifacts/review-website/browser-fixture-archive.json', JSON.stringify(report, null, 2));
console.log(JSON.stringify({ matched: candidates.length, archived: archived.length, originalsProtected: original.size, deletedRows: 0 }));
